    border-right: 1px solid #202225;
    padding: 0.5rem 0;
}

::deep .channel-list-header {
    padding: 0.75rem 1rem;
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #8e9297;
    margin: 0;
}

::deep .channel-item {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    padding: 0.5rem 1rem;
    cursor: pointer;
    border-radius: 4px;
    margin: 0 0.5rem;
    transition: background 0.15s;
}

::deep .channel-item:hover {
    background: #36393f;
}

::deep .channel-item.active {
    background: #393c43;
    color: #fff;
}

::deep .channel-name {
    font-weight: 600;
    flex: 1;
}

::deep .channel-desc {
    width: 100%;
    font-size: 0.75rem;
    color: #8e9297;
    margin-top: 0.15rem;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

::deep .unread-badge {
    background: #ed4245;
    color: #fff;
    border-radius: 9px;
    padding: 0.1rem 0.5rem;
    font-size: 0.7rem;
    font-weight: 700;
}

/* Main message area */
.main-panel {
    display: flex;
    flex-direction: column;
    flex: 1;
    min-width: 0;
    transition: width 0.2s;
}

.main-panel.full-width {
    width: 80%;
}

.main-panel.with-thread {
    width: 55%;
}

::deep .message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #36393f;
    color: #dcddde;
}

::deep .message-area-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #202225;
    background: #36393f;
}

::deep .message-area-header h2 {
    margin: 0;
    font-size: 1rem;
    color: #fff;
}

::deep .message-area-header p {
    margin: 0.25rem 0 0;
    font-size: 0.8rem;
    color: #8e9297;
}

::deep .message-list {
    flex: 1;
    overflow-y: auto;
    padding: 1rem;
}

::deep .loading-indicator {
    text-align: center;
    color: #8e9297;
    padding: 0.5rem;
    font-size: 0.85rem;
}

/* Message items */
::deep .message-item {
    position: relative;
    padding: 0.5rem 0.75rem;
    border-radius: 4px;
    margin-bottom: 0.25rem;
    transition: background 0.1s;
}

::deep .message-item:hover {
    background: #32353b;
}

::deep .message-item.highlighted {
    background: #3b3e45;
}

::deep .message-header {
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
}

::deep .author {
    font-weight: 600;
    color: #fff;
    font-size: 0.9rem;
}

::deep .timestamp {
    font-size: 0.7rem;
    color: #72767d;
}

::deep .message-content {
    margin-top: 0.2rem;
    line-height: 1.4;
    word-break: break-word;
}

::deep .reactions {
    display: flex;
    gap: 0.35rem;
    margin-top: 0.4rem;
    flex-wrap: wrap;
}

::deep .reaction-badge {
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 4px;
    padding: 0.1rem 0.4rem;
    font-size: 0.8rem;
    cursor: default;
}

::deep .thread-link {
    background: none;
    border: none;
    color: #00aff4;
    font-size: 0.8rem;
    cursor: pointer;
    padding: 0.25rem 0;
    margin-top: 0.25rem;
}

::deep .thread-link:hover {
    text-decoration: underline;
}

::deep .message-actions {
    position: absolute;
    top: -0.5rem;
    right: 0.5rem;
    display: flex;
    gap: 0.25rem;
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 4px;
    padding: 0.2rem;
    z-index: 10;
}

::deep .action-btn {
    background: none;
    border: none;
    color: #dcddde;
    font-size: 0.75rem;
    cursor: pointer;
    padding: 0.2rem 0.4rem;
    border-radius: 3px;
}

::deep .action-btn:hover {
    background: #4f545c;
}

::deep .emoji-picker {
    display: flex;
    gap: 0.25rem;
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 4px;
    padding: 0.3rem;
    margin-top: 0.25rem;
    width: fit-content;
