    padding: 0.2rem;
    border-radius: 3px;
}

::deep .emoji-btn:hover {
    background: #4f545c;
}

/* Message input */
::deep .message-input {
    display: flex;
    gap: 0.5rem;
    padding: 0.75rem 1rem;
    background: #36393f;
    border-top: 1px solid #202225;
}

::deep .message-input textarea {
    flex: 1;
    resize: none;
    background: #40444b;
    border: none;
    border-radius: 8px;
    padding: 0.6rem 0.75rem;
    color: #dcddde;
    font-size: 0.9rem;
    font-family: inherit;
