+/* Chat page layout */
+.chat-layout {
+    display: flex;
+    height: 100vh;
+    overflow: hidden;
+    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
+}
+
+/* Channel sidebar */
+::deep .channel-list {
+    width: 20%;
+    min-width: 200px;
