+    text-transform: uppercase;
+    letter-spacing: 0.05em;
+    color: #8e9297;
+    margin: 0;
+}
+
+::deep .channel-item {
+    display: flex;
+    flex-wrap: wrap;
+    align-items: center;
+    padding: 0.5rem 1rem;
+    cursor: pointer;
+    border-radius: 4px;
+    margin: 0 0.5rem;
+    transition: background 0.15s;
+}
+
+::deep .channel-item:hover {
+    background: #36393f;
+}
+
+::deep .channel-item.active {
+    background: #393c43;
+    color: #fff;
+}
+
+::deep .channel-name {
+    font-weight: 600;
+    flex: 1;
+}
+
+::deep .channel-desc {
+    width: 100%;
+    font-size: 0.75rem;
+    color: #8e9297;
+    margin-top: 0.15rem;
+    white-space: nowrap;
+    overflow: hidden;
+    text-overflow: ellipsis;
+}
+
+::deep .unread-badge {
+    background: #ed4245;
+    color: #fff;
+    border-radius: 9px;
+    padding: 0.1rem 0.5rem;
+    font-size: 0.7rem;
+    font-weight: 700;
+}
+
+/* Main message area */
+.main-panel {
+    display: flex;
+    flex-direction: column;
+    flex: 1;
+    min-width: 0;
+    transition: width 0.2s;
+}
+
+.main-panel.full-width {
+    width: 80%;
+}
+
+.main-panel.with-thread {
+    width: 55%;
+}
+
+::deep .message-area {
+    display: flex;
+    flex-direction: column;
+    height: 100%;
+    background: #36393f;
+    color: #dcddde;
+}
+
+::deep .message-area-header {
+    padding: 0.75rem 1rem;
