+}
+
+::deep .message-area-header h2 {
+    margin: 0;
+    font-size: 1rem;
+    color: #fff;
+}
+
+::deep .message-area-header p {
+    margin: 0.25rem 0 0;
+    font-size: 0.8rem;
+    color: #8e9297;
+}
+
+::deep .message-list {
+    flex: 1;
+    overflow-y: auto;
+    padding: 1rem;
+}
+
+::deep .loading-indicator {
+    text-align: center;
+    color: #8e9297;
+    padding: 0.5rem;
+    font-size: 0.85rem;
+}
+
+/* Message items */
+::deep .message-item {
+    position: relative;
+    padding: 0.5rem 0.75rem;
+    border-radius: 4px;
+    margin-bottom: 0.25rem;
+    transition: background 0.1s;
+}
+
+::deep .message-item:hover {
+    background: #32353b;
+}
+
+::deep .message-item.highlighted {
+    background: #3b3e45;
+}
+
+::deep .message-header {
+    display: flex;
+    align-items: baseline;
+    gap: 0.5rem;
+}
+
+::deep .author {
+    font-weight: 600;
+    color: #fff;
+    font-size: 0.9rem;
+}
+
+::deep .timestamp {
+    font-size: 0.7rem;
+    color: #72767d;
+}
+
+::deep .message-content {
+    margin-top: 0.2rem;
+    line-height: 1.4;
+    word-break: break-word;
+}
+
+::deep .reactions {
+    display: flex;
+    gap: 0.35rem;
+    margin-top: 0.4rem;
+    flex-wrap: wrap;
+}
+
+::deep .reaction-badge {
+    background: #2f3136;
+    border: 1px solid #4f545c;
+    border-radius: 4px;
+    padding: 0.1rem 0.4rem;
+    font-size: 0.8rem;
+    cursor: default;
+}
+
+::deep .thread-link {
+    background: none;
+    border: none;
+    color: #00aff4;
+    font-size: 0.8rem;
+    cursor: pointer;
+    padding: 0.25rem 0;
+    margin-top: 0.25rem;
+}
+
+::deep .thread-link:hover {
+    text-decoration: underline;
+}
+
+::deep .message-actions {
+    position: absolute;
+    top: -0.5rem;
+    right: 0.5rem;
+    display: flex;
+    gap: 0.25rem;
+    background: #2f3136;
+    border: 1px solid #4f545c;
+    border-radius: 4px;
+    padding: 0.2rem;
+    z-index: 10;
+}
+
+::deep .action-btn {
+    background: none;
+    border: none;
+    color: #dcddde;
+    font-size: 0.75rem;
+    cursor: pointer;
+    padding: 0.2rem 0.4rem;
+    border-radius: 3px;
+}
+
+::deep .action-btn:hover {
+    background: #4f545c;
+}
+
+::deep .emoji-picker {
+    display: flex;
+    gap: 0.25rem;
+    background: #2f3136;
+    border: 1px solid #4f545c;
+    border-radius: 4px;
+    padding: 0.3rem;
+    margin-top: 0.25rem;
+    width: fit-content;
+}
+
+::deep .emoji-btn {
+    background: none;
+    border: none;
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 0.2rem;
+    border-radius: 3px;
+}
+
+::deep .emoji-btn:hover {
+    background: #4f545c;
+}
+
+/* Message input */
+::deep .message-input {
+    display: flex;
+    gap: 0.5rem;
+    padding: 0.75rem 1rem;
+    background: #36393f;
+    border-top: 1px solid #202225;
+}
+
+::deep .message-input textarea {
+    flex: 1;
+    resize: none;
+    background: #40444b;
+    border: none;
+    border-radius: 8px;
+    padding: 0.6rem 0.75rem;
+    color: #dcddde;
+    font-size: 0.9rem;
+    font-family: inherit;
+    outline: none;
+}
+
+::deep .message-input textarea:focus {
+    box-shadow: 0 0 0 2px #5865f2;
+}
+
+::deep .send-btn {
+    background: #5865f2;
+    color: #fff;
+    border: none;
+    border-radius: 8px;
+    padding: 0.6rem 1rem;
+    font-weight: 600;
+    cursor: pointer;
+    white-space: nowrap;
+}
+
+::deep .send-btn:hover:not(:disabled) {
+    background: #4752c4;
+}
+
+::deep .send-btn:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+
+/* Thread panel */
+::deep .thread-panel {
+    width: 25%;
+    min-width: 250px;
+    background: #2f3136;
+    color: #dcddde;
+    border-left: 1px solid #202225;
+    display: flex;
+    flex-direction: column;
+    height: 100%;
+}
+
+::deep .thread-header {
+    display: flex;
+    align-items: center;
+    justify-content: space-between;
+    padding: 0.75rem 1rem;
+    border-bottom: 1px solid #202225;
+}
+
+::deep .thread-header h3 {
+    margin: 0;
+    font-size: 1rem;
+    color: #fff;
+}
+
+::deep .close-btn {
+    background: none;
+    border: none;
+    color: #dcddde;
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 0.2rem 0.5rem;
+    border-radius: 4px;
+}
+
+::deep .close-btn:hover {
+    background: #4f545c;
+}
+
+::deep .thread-root-message {
+    padding: 0.75rem 1rem;
+    border-bottom: 1px solid #202225;
+    background: #36393f;
+}
+
+::deep .thread-root-message .author {
+    font-size: 0.85rem;
+}
+
+::deep .thread-root-message .content {
+    margin: 0.3rem 0 0;
+    font-size: 0.9rem;
+    line-height: 1.4;
+}
+
+::deep .thread-replies {
+    flex: 1;
+    overflow-y: auto;
+    padding: 0.75rem 1rem;
+}
+
+::deep .thread-reply {
+    padding: 0.4rem 0;
+    border-bottom: 1px solid #36393f;
+}
+
+/* No channel state */
+.no-channel-selected {
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    height: 100%;
+    background: #36393f;
+    color: #8e9297;
+    font-size: 1.1rem;
+}
+

